import { OPTION_NAME } from './constants.mjs';
import {
  buildExpectedArgumentError,
  buildHelpText,
  buildRequiredArgumentError,
  buildUnrecognizedArgumentsError,
} from './helpText.mjs';

function isNegativeNumberToken(token) {
  if (typeof token !== 'string' || token.length < 2 || token[0] !== '-' || token[1] === '-') {
    return false;
  }

  return !Number.isNaN(Number(token));
}

function isOptionLikeToken(token) {
  return typeof token === 'string' && token.startsWith('-') && !isNegativeNumberToken(token);
}

export function parseCliArgs(argv, scriptPath) {
  let optionA;
  let hasOptionA = false;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return { kind: 'help', text: buildHelpText(scriptPath) };
    }

    if (token === '--') {
      extras.push(...argv.slice(index));
      break;
    }

    if (token === OPTION_NAME) {
      const nextToken = argv[index + 1];

      if (nextToken === undefined || nextToken === '--' || isOptionLikeToken(nextToken)) {
        return { kind: 'error', exitCode: 2, text: buildExpectedArgumentError(scriptPath) };
      }

      optionA = nextToken;
      hasOptionA = true;
      index += 1;
      continue;
    }

    if (typeof token === 'string' && token.startsWith(`${OPTION_NAME}=`)) {
      optionA = token.slice(OPTION_NAME.length + 1);
      hasOptionA = true;
      continue;
    }

    extras.push(token);
  }

  if (!hasOptionA) {
    return { kind: 'error', exitCode: 2, text: buildRequiredArgumentError(scriptPath) };
  }

  if (extras.length > 0) {
    return { kind: 'error', exitCode: 2, text: buildUnrecognizedArgumentsError(scriptPath, extras) };
  }

  return { kind: 'ok', optionA };
}

import { parseCliArgs } from './argv.mjs';
import { runPythonExecutable } from './executableBridge.mjs';

function writeBuffer(stream, value) {
  if (value && value.length > 0) {
    stream.write(value);
  }
}

export function runCli(argv, io = {}) {
  const stdout = io.stdout ?? process.stdout;
  const stderr = io.stderr ?? process.stderr;
  const scriptPath = io.scriptPath ?? process.argv[1] ?? 'test2.mjs';
  const parsed = parseCliArgs(argv, scriptPath);

  if (parsed.kind === 'help') {
    stdout.write(parsed.text);
    return 0;
  }

  if (parsed.kind === 'error') {
    stderr.write(parsed.text);
    return parsed.exitCode;
  }

  const execution = runPythonExecutable(argv);

  if (execution.kind === 'error') {
    stderr.write(`${execution.message}\n`);
    return 1;
  }

  writeBuffer(stdout, execution.stdout);
  writeBuffer(stderr, execution.stderr);
  return execution.status;
}

import { runCli } from './lib/main.mjs';

process.exitCode = runCli(process.argv.slice(2), {
  stdout: process.stdout,
  stderr: process.stderr,
  scriptPath: process.argv[1] ?? 'test2.mjs',
});

import { basename } from 'node:path';
import { OPTION_NAME, OPTION_VALUE_NAME } from './constants.mjs';

function getProgramName(scriptPath) {
  return basename(scriptPath || 'test2.mjs');
}

function getUsageLine(scriptPath) {
  return `usage: ${getProgramName(scriptPath)} [-h] ${OPTION_NAME} ${OPTION_VALUE_NAME}`;
}

export function buildHelpText(scriptPath) {
  return `${getUsageLine(scriptPath)}\n\noptions:\n  -h, --help  show this help message and exit\n  ${OPTION_NAME} ${OPTION_VALUE_NAME}\n`;
}

export function buildRequiredArgumentError(scriptPath) {
  return `${getUsageLine(scriptPath)}\n${getProgramName(scriptPath)}: error: the following arguments are required: ${OPTION_NAME}\n`;
}

export function buildExpectedArgumentError(scriptPath) {
  return `${getUsageLine(scriptPath)}\n${getProgramName(scriptPath)}: error: argument ${OPTION_NAME}: expected one argument\n`;
}

export function buildUnrecognizedArgumentsError(scriptPath, extras) {
  return `${getUsageLine(scriptPath)}\n${getProgramName(scriptPath)}: error: unrecognized arguments: ${extras.join(' ')}\n`;
}

import { spawnSync } from 'node:child_process';
import { PYTHON_EXECUTABLE_PATH } from './constants.mjs';

export function runPythonExecutable(argv) {
  const result = spawnSync(PYTHON_EXECUTABLE_PATH, argv, { encoding: null });

  if (result.error) {
    return { kind: 'error', message: result.error.message };
  }

  return {
    kind: 'ok',
    status: result.status ?? 1,
    stdout: result.stdout ?? Buffer.alloc(0),
    stderr: result.stderr ?? Buffer.alloc(0),
  };
}

export const PYTHON_EXECUTABLE_PATH = '/workspace/dataset/test2_executable';
export const OPTION_NAME = '--a';
export const OPTION_VALUE_NAME = 'A';
